// NO_AUTO_TRANSPILE
//  ---------------------------------------------------------------------------
//  OrderRouter — LIVE execution against a real venue.
//
//  Run:  ORDER_ROUTER_LIVE_VENUE=1 \
//        BINANCE_TESTNET_APIKEY=... BINANCE_TESTNET_SECRET=... \
//        npx tsx --test ts/src/test/base/test.orderRouter.execute.live.ts
//
//  Skipped in full unless ORDER_ROUTER_LIVE_VENUE is exactly '1' AND both
//  credentials are present. Two independent gates on purpose: an env var that
//  happens to be set in someone's shell must not start placing orders.
//
//  WHAT THIS COVERS THAT NOTHING ELSE DOES. Every other OrderRouter test stubs
//  the venue. The stubs return what this implementation believes a venue
//  returns — so they prove the six ports agree with each other, not that any of
//  them agrees with an exchange. These place REAL ORDERS on a REAL MATCHING
//  ENGINE and assert on what comes back: that a resting limit is cancelled and
//  leaves nothing behind, that a crossing IOC fills and reconciles, that the
//  re-execution guard refuses the replay, and that the position is flat
//  afterwards.
//
//  THE VENUE IS BINANCE USDS-M FUTURES TESTNET. Play money, and the only
//  Binance host reachable from CI: mainnet, the spot testnet and the demo
//  trading hosts are all geo-blocked (451) from most datacentre ranges.
//  options.disableFuturesSandboxWarning is ccxt's own escape hatch for the
//  futures-sandbox deprecation — the testnet is still live, it is just no
//  longer the recommended path.
//
//  CLAUDE.md §5.5 IS ENFORCED HERE, NOT ASSUMED. The notional is computed from
//  the live book before every order and the test ABORTS above the cap rather
//  than shrinking silently. Every position this file opens is closed in a
//  finally, reduce-only, and the final assertion is that the position is back
//  where it started. withdraw is never called, here or anywhere in OrderRouter.
//  ---------------------------------------------------------------------------
import assert from 'assert';
import { test } from 'node:test';
import ccxt from '../../../ccxt.js';
import OrderRouter from '../../base/OrderRouter.js';
import { BadRequest } from '../../base/errors.js';
const apiKey = process.env['BINANCE_TESTNET_APIKEY'];
const secret = process.env['BINANCE_TESTNET_SECRET'];
const enabled = process.env['ORDER_ROUTER_LIVE_VENUE'] === '1';
let skip = false;
if (!enabled) {
    skip = 'ORDER_ROUTER_LIVE_VENUE is not 1';
}
else if (apiKey === undefined || secret === undefined || apiKey === '' || secret === '') {
    skip = 'BINANCE_TESTNET_APIKEY / BINANCE_TESTNET_SECRET are not set';
}
//  A liquid perpetual whose MIN_NOTIONAL is 5 USDT, so a real fill fits under the
//  25 USD cap. BTC/USDT:USDT and ETH/USDT:USDT do NOT — their minimums are 50 and
//  20 — which is exactly the case CLAUDE.md says to skip rather than shrink.
const SYMBOL = 'XRP/USDT:USDT';
const TARGET_USD = 12;
const CAP_USD = 25;
function venue() {
    const exchange = new ccxt.binance({
        'apiKey': apiKey,
        'secret': secret,
        'enableRateLimit': true,
        'options': {
            'defaultType': 'swap',
            //  the spot testnet host is geo-blocked even where the futures one is
            //  not, so only linear markets are loaded
            'fetchMarkets': { 'types': ['linear'] },
            //  both are sapi calls against the geo-blocked mainnet host
            'fetchCurrencies': false,
            'fetchMargins': false,
            'disableFuturesSandboxWarning': true,
        },
    });
    exchange.setSandboxMode(true);
    return exchange;
}
async function netPosition(exchange) {
    const positions = await exchange.fetchPositions([SYMBOL]);
    for (let i = 0; i < positions.length; i++) {
        if (positions[i]['symbol'] === SYMBOL) {
            const size = positions[i]['contracts'];
            return (positions[i]['side'] === 'short') ? -size : size;
        }
    }
    return 0;
}
//  A route of the shape the service returns, priced off the venue's OWN book, so
//  every number below is real even though no router service is involved. This is
//  the caller-assembled path: execute never asks where a plan came from.
function routeAt(price, amount, tag) {
    return {
        'requestId': 'live-' + tag + '-' + Date.now().toString(),
        'calculatedAt': Date.now(),
        'from': 'USDT',
        'to': 'XRP',
        'strategy': 'best_price',
        'exactSide': 'in',
        'amountIn': amount * price,
        'amountOut': amount,
        'fullyFillable': true,
        'fillRatio': 1,
        'hops': [{
                'pair': SYMBOL,
                'side': 'buy',
                'base': 'XRP',
                'quote': 'USDT',
                'legs': [{ 'exchangeId': 'binance', 'amount': amount, 'averagePrice': price, 'effectivePrice': price }],
            }],
    };
}
//  CLAUDE.md §5.5: compute the notional before every order and ABORT at the cap.
//  Never shrink to fit — a test that quietly resizes is a cap that does not exist.
function assertUnderCap(amount, price, what) {
    const notional = amount * price;
    assert.ok(notional < CAP_USD, what + ' notional ' + notional.toFixed(2) + ' USD must stay under the ' + CAP_USD.toString() + ' USD cap');
}
async function flatten(exchange, opened) {
    if (opened === 0) {
        return;
    }
    const side = (opened > 0) ? 'sell' : 'buy';
    const quantity = Math.abs(opened);
    const price = (await exchange.fetchTicker(SYMBOL))['last'];
    assertUnderCap(quantity, price, 'the cleanup order');
    await exchange.createOrder(SYMBOL, 'market', side, quantity, undefined, { 'reduceOnly': true });
}
test('live: a resting limit is polled, cancelled, and leaves nothing behind', { 'skip': skip }, async () => {
    const exchange = venue();
    await exchange.loadMarkets();
    const before = await netPosition(exchange);
    const book = await exchange.fetchOrderBook(SYMBOL, 5);
    const bestBid = book['bids'][0][0];
    const amount = Number((TARGET_USD / bestBid).toFixed(1));
    //  30% below the bid: a real order on a real book that cannot fill, which is
    //  what makes the cancel path observable without taking a position
    const restingPrice = bestBid * 0.7;
    assertUnderCap(amount, bestBid, 'the resting order');
    const router = new OrderRouter({ 'apiKey': 'not-used-on-this-path', 'maxNotionalUsd': CAP_USD });
    const plan = router.buildExecutionPlan(routeAt(restingPrice, amount, 'resting'), { 'slippageBps': 20 });
    const events = [];
    let opened = 0;
    try {
        const report = await router.execute(plan, { 'binance': exchange }, {
            'strategy': 'limit_protected',
            'live': true,
            'usdRates': { 'USDT': 1, 'XRP': bestBid },
            'maxNotionalUsd': CAP_USD,
            'orderTimeoutMs': 4000,
            'pollIntervalMs': 1000,
            'onStep': (event) => { events.push(event); return 'continue'; },
        });
        const step = report['steps'][0];
        assert.strictEqual(step['status'], 'unfilled', 'a limit 30% away does not fill');
        assert.strictEqual(step['filledAmount'], 0);
        assert.ok(step['orderId'] !== '', 'the venue accepted the order and the report names it');
        assert.strictEqual(report['halted'], true, 'nothing filled, so the route halts');
        assert.strictEqual(report['haltReason'], 'nothing_filled');
        assert.deepStrictEqual(report['openOrders'], [], 'the cancel succeeded, so nothing is recorded as left open');
        assert.deepStrictEqual(report['errors'], []);
        assert.strictEqual(events.length, 1, 'onStep fired once, after the step reconciled');
        opened = (await netPosition(exchange)) - before;
    }
    finally {
        await flatten(exchange, opened);
        //  the claim report.openOrders makes is about the VENUE, so ask the venue
        const open = await exchange.fetchOpenOrders(SYMBOL);
        assert.strictEqual(open.length, 0, 'no order is left resting on the venue');
        assert.strictEqual(await netPosition(exchange), before, 'the position is back where it started');
    }
});
test('live: a crossing IOC fills, reconciles, and cannot be replayed', { 'skip': skip }, async () => {
    const exchange = venue();
    await exchange.loadMarkets();
    const before = await netPosition(exchange);
    const book = await exchange.fetchOrderBook(SYMBOL, 5);
    const bestAsk = book['asks'][0][0];
    const amount = Number((TARGET_USD / bestAsk).toFixed(1));
    assertUnderCap(amount, bestAsk, 'the taking order');
    const router = new OrderRouter({ 'apiKey': 'not-used-on-this-path', 'maxNotionalUsd': CAP_USD });
    //  50bps above the ask, so the IOC crosses the book rather than expiring
    const plan = router.buildExecutionPlan(routeAt(bestAsk, amount, 'fill'), { 'slippageBps': 50 });
    const options = {
        'strategy': 'sequential',
        'live': true,
        'usdRates': { 'USDT': 1, 'XRP': bestAsk },
        'maxNotionalUsd': CAP_USD,
        //  a plan built seconds ago from this venue's own book; the check is here
        //  to prove the freshness gate passes a plan that IS fresh
        'maxPlanAgeMs': 120000,
    };
    let opened = 0;
    try {
        const report = await router.execute(plan, { 'binance': exchange }, options);
        const step = report['steps'][0];
        assert.strictEqual(step['status'], 'filled');
        assert.ok(step['filledAmount'] > 0, 'a crossing IOC fills');
        assert.ok(step['averagePrice'] > 0, 'and the fill price is observed, not assumed');
        assert.strictEqual(step['filledKnown'], true, 'the venue told us the fill, it was not inferred');
        assert.strictEqual(report['halted'], false);
        assert.deepStrictEqual(report['openOrders'], []);
        assert.deepStrictEqual(report['errors'], []);
        assert.ok(report['planAgeMs'] >= 0, 'a plan carrying calculatedAt reports a real age');
        //  the unwind plan is built out of what ACTUALLY happened, so it mirrors
        //  the fill rather than the plan
        const unwind = router.buildUnwindPlan(report);
        assert.strictEqual(unwind['steps'].length, 1);
        assert.strictEqual(unwind['steps'][0]['side'], 'sell', 'unwinding a buy is a sell');
        assert.strictEqual(unwind['steps'][0]['amount'], step['filledAmount'], 'of exactly what filled');
        //  the guard that exists to stop a double-fill, against a venue that would
        //  cheerfully take the second order
        await assert.rejects(async () => {
            await router.execute(plan, { 'binance': exchange }, options);
        }, BadRequest, 'the same plan is refused on a second live execution');
        opened = (await netPosition(exchange)) - before;
        assert.ok(Math.abs(opened) > 0, 'the fill really moved the position');
    }
    finally {
        await flatten(exchange, opened);
        const open = await exchange.fetchOpenOrders(SYMBOL);
        assert.strictEqual(open.length, 0, 'an IOC leaves nothing resting');
        assert.strictEqual(await netPosition(exchange), before, 'the position is flat again');
    }
});
